from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    # Locate the full-length divider.
    divider = next((("c", c) for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    if divider is None:
        divider = next((("r", r) for r in range(h) if all(v == 2 for v in grid[r])), None)
    out = [row[:] for row in grid]
    if divider is None:
        return out
    axis, pos = divider
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (background, 2)]
    if not cells:
        return out
    color = grid[cells[0][0]][cells[0][1]]
    cells = [(r, c) for r, c in cells if grid[r][c] == color]
    if axis == "c":
        side = 1 if min(c for r, c in cells) > pos else -1
        near = min(c for r, c in cells) if side == 1 else max(c for r, c in cells)
        shift = pos + side - near
        moved = [(r, c + shift) for r, c in cells]
        for r, c in cells:
            out[r][c] = background
        for r, c in moved:
            if 0 <= c < w:
                out[r][c] = color
        edge = (max(c for r, c in moved) + 1) if side == 1 else (min(c for r, c in moved) - 1)
        if 0 <= edge < w:
            for r in range(h):
                out[r][edge] = 8
    else:
        side = 1 if min(r for r, c in cells) > pos else -1
        near = min(r for r, c in cells) if side == 1 else max(r for r, c in cells)
        shift = pos + side - near
        moved = [(r + shift, c) for r, c in cells]
        for r, c in cells:
            out[r][c] = background
        for r, c in moved:
            if 0 <= r < h:
                out[r][c] = color
        edge = (max(r for r, c in moved) + 1) if side == 1 else (min(r for r, c in moved) - 1)
        if 0 <= edge < h:
            for c in range(w):
                out[edge][c] = 8
    return out
